/* Raw primary-slot projection only; no serialized generation admission. */
static void slot_word(unsigned char*out,unsigned cap,unsigned*at,U32 v){assert(*at<=cap&&cap-*at>=4);for(unsigned i=0;i<4;i++)out[(*at)++]=(unsigned char)(v>>(i*8));}
static void dump_slots(unsigned char*out,unsigned cap,unsigned*at,cStashTable table){slot_word(out,cap,at,table->uiMaxSize);slot_word(out,cap,at,table->uiValidValues);for(unsigned i=0;i<table->uiMaxSize;i++){const StashElementImp*e=&table->pStorage[i];unsigned present=!slotEmpty(e)&&!slotDeleted(e);slot_word(out,cap,at,present);if(present){if(table->eKeyType==StashKeyTypeInts)slot_word(out,cap,at,PTR_TO_U32(e->key.pKey));else{const char*s=e->key.pKey;unsigned n=strlen(s);slot_word(out,cap,at,n);assert(*at<=cap&&n<=cap-*at);memcpy(out+*at,s,n);*at+=n;}}}}
unsigned original_primary_builder(const unsigned char*input,unsigned size,const unsigned char*palette,unsigned palette_size,unsigned char*out,unsigned cap,unsigned char*trace_out,unsigned trace_capacity,unsigned*stats,unsigned scenario){
 assert(size<=32*1024*1024&&palette_size<=65536&&cap<=16*1024*1024&&trace_capacity<=32*1024*1024);reset();memset(&gCostumeMaster,0,sizeof(gCostumeMaster));memset(&gSuperPalette,0,sizeof(gSuperPalette));SimpleBuffer in={(char*)input,size,48116,size},colors={(char*)palette,palette_size,92,palette_size};int sum=0;assert(ParserReadBinaryTable(&in,ParseCostumeSet,&gCostumeMaster,&sum)&&in.curposition==(int)size);sum=0;assert(ParserReadBinaryTable(&colors,ParseColorPalette,&gSuperPalette,&sum)&&colors.curposition==(int)palette_size);
 costume_HashTable=NULL;costume_HashTableExtraInfo=NULL;costume_PaletteTable=NULL;trace_mode=0;
 assert(scenario<=3);callback_mode=scenario!=0;callback_policy=scenario;callback_sku_calls=callback_errors=0;if(callback_mode)assert(costume_fillExtraData(ParseCostumeSet,&gCostumeMaster,scenario&1));callback_mode=0;
 costume_HashTable=NULL;costume_HashTableExtraInfo=NULL;costume_PaletteTable=NULL;costumeReward_HashTable=NULL;costume_TaggedPartTable=NULL;costume_GeoDataTable=NULL;memset(ancillary_adds,0,sizeof(ancillary_adds));tag_calls=geo_calls=0;trace=trace_out;trace_size=0;trace_cap=trace_capacity;trace_mode=1;stash_allocations=0;
 costume_initHashTable();trace_mode=0;unsigned at=0;dump_slots(out,cap,&at,costume_HashTable);dump_slots(out,cap,&at,costume_HashTableExtraInfo);dump_slots(out,cap,&at,costume_PaletteTable);
 stats[0]=at;stats[1]=trace_size;stats[2]=costume_HashTable->uiMaxSize;stats[3]=costume_HashTable->uiValidValues;stats[4]=costume_HashTableExtraInfo->uiMaxSize;stats[5]=costume_HashTableExtraInfo->uiValidValues;stats[6]=costume_PaletteTable->uiMaxSize;stats[7]=costume_PaletteTable->uiValidValues;stats[8]=stash_allocations;stats[9]=tag_calls;stats[10]=geo_calls;stats[11]=memory_peak;stats[12]=callback_sku_calls;stats[13]=callback_errors;
 free(costume_HashTable->pStorage);free((void*)costume_HashTable);free(costume_HashTableExtraInfo->pStorage);free((void*)costume_HashTableExtraInfo);free(costume_PaletteTable->pStorage);free((void*)costume_PaletteTable);reset();return at;
}
const char*original_builder_schema_name(unsigned table,unsigned col){assert(table<original_schema_count());return all_tables[table][col].name;}
